'use strict'


class Cache {
  /** @type {Map<string, [unknown, number]>} */
  #entries = new Map()

  /**
   * @param {string} key
   */
  has (key) {
    return this.#entries.has(key)
  }

  /**
   * @param {string} key
   * @param {unknown} value
   */
  set (key, value) {
    return this.#entries.set(key, [value, Date.now()])
  }

  /**
   * @param {string} key
   */
  get (key) {
    return this.#entries.get(key)?.[0]
  }

  dump () {
    /** @type {Record<string, { key: string, value: unknown, timestamp: Date }>} */
    const dump = {}
    for (const [key, value] of this.#entries.entries()) {
      const timestamp = new Date(value[1])
      dump[key] = { key, value: value[0], timestamp }
    }
    return JSON.stringify(dump, null, 2)
  }

  /**
   * @param {string} key
   */
  remove (key) {
    if (this.#entries.has(key)) {
      this.#entries.delete(key)
    }
  }

  clear () {
    this.#entries.clear()
  }
}


module.exports = {
  Cache,
  globalCache: new Cache(),
}
